/**
 * @file problem.hpp
 * @brief The triad_count problem on the framework (cpp/src/framework), over the
 *        hypergraph: its hooks, its state and its workspace (generated by
 *        scripts/new_algorithm.py --container hypergraph).
 *
 * Template card (PLAN Section 4.5.2; docs/developer/framework.md):
 *
 *     normalize -> prepare -> before_apply -> count(-) on G_t -> commit ->
 *     identify_affected -> count(+) on G_{t+1} -> finalize
 *
 * An aggregate-delta problem with the exactly-once rule ownership::min_member (invariant I2). The
 * placeholder ("start green", PLAN Section 4.8) leaves count(-) empty and recounts everything in
 * count(+) (finalize sets stats::fallback_used = true), so update() recomputes. To make it
 * incremental: in before_apply, take the deleted ids of G_t (batch.normalized->deletions) as the
 * frontier and count in count(-) on the OLD views what they carry; in identify_affected, take
 * the inserted ids (applied.summary.inserted_ids; applied.record.inserted_ids_device on CUDA) and
 * count in count(+) on the NEW views what they bring, each pattern attributed to its smallest
 * changed id; in finalize, apply the signed delta.
 *
 * The views: the public h2v(), v2h() and h2h() (built at most once per version, the container's
 * work), or the internal row views of detail::hypergraph_access::views() (rebuilt by every
 * commit; what the kernels of triad_count read). compute() is the static enactor with the same
 * hooks (reset first). Lifecycle members without a stage: begin_update (the checks before
 * anything changes), resume (bind G_{t+1}, lease the workspace), end_update (record the
 * hypergraph state), poison.
 */
#pragma once

#include "framework/budgets.hpp"
#include "framework/composition.hpp"
#include "framework/context.hpp"
#include "framework/frontier.hpp"
#include "framework/policies.hpp"
#include "framework/problem.hpp"
#include "framework/views.hpp"
#include "framework/workspace.hpp"

#include <dyng/core/array_view.hpp>
#include <dyng/core/backend.hpp>
#include <dyng/core/resources.hpp>
#include <dyng/hypergraph/hypergraph.hpp>
#include <dyng/triad_count.hpp>

#include <cstddef>
#include <cstdint>
#include <optional>
#include <string_view>
#include <vector>

namespace dyng::detail {

/// The state behind an triad_count::result.
struct triad_count_state {
  triad_count::options opt;       ///< the options
  std::uint64_t count = 0;        ///< the aggregate
  std::uint64_t version = 0;      ///< hypergraph version matched
  std::uint64_t graph_state = 0;  ///< hypergraph state matched (ADR 0006, "Graph identity")
  bool poisoned = false;          ///< a failed update left the result unusable
};

/// Access to the state of a result.
struct triad_count_access {
  /// The state of `r`.
  static triad_count_state& state(triad_count::result& r);
  /// The state of `r`.
  static const triad_count_state& state(const triad_count::result& r);
  /// A result owning `st`.
  static triad_count::result make(std::unique_ptr<triad_count_state> st);
};

/// Scratch space of the engines, leased from the workspace pool of the resources handle (ADR 0015).
struct triad_count_workspace final : pooled_workspace {
  std::vector<std::int64_t> unused;  ///< TODO(triad_count): the scratch of the counts

  /// Size the arrays for `n` vertices (a reservation when they grow, invariant I9).
  void reserve(std::size_t n);

  /// Bytes of the arrays' capacities.
  [[nodiscard]] std::size_t bytes() const noexcept override;
};

/**
 * @brief The static count on the sequential backend: the incidences (the sum of |e|).
 * @param[in] row_ptr h2v offsets (host).
 * @return The count.
 */
std::uint64_t triad_count_sequential(array_view<const std::int64_t> row_ptr);

/**
 * @brief The static count on the OpenMP backend (as triad_count_sequential()).
 * @param[in] res     The resources (their thread count).
 * @param[in] row_ptr h2v offsets (host).
 * @return The count.
 */
std::uint64_t triad_count_openmp(const resources& res, array_view<const std::int64_t> row_ptr);

/// The update family of triad_count.
inline constexpr framework::family triad_count_family = framework::family::aggregate_delta;

/**
 * @brief The triad_count problem (see the file comment).
 * @tparam vertex_t Vertex id type.
 * @tparam weight_t Hyperedge weight type.
 */
template <typename vertex_t, typename weight_t>
class triad_count_problem final
    : public framework::problem_base<triad_count_problem<vertex_t, weight_t>, triad_count_family> {
 public:
  static constexpr std::string_view name = "triad_count";   ///< stages "<name>.<hook>"
  using container_type = hypergraph<vertex_t, weight_t>;    ///< the container
  using stats_type = triad_count::stats;                    ///< the stats of update()
  using frontier_type = framework::internal_frontier;       ///< frontiers are internal
  using ownership_type = framework::ownership::min_member;  ///< the counting rule (I2)
  using old_graph = framework::old_view<container_type>;    ///< G_t
  using new_graph = framework::new_view<container_type>;    ///< G_{t+1}
  /// The batch before the commit (batch.normalized: Step 0, the live deletions of G_t).
  using requested = framework::hyper_requested_batch<vertex_t, weight_t>;
  /// What the commit did (applied.summary.inserted_ids; applied.record: the applied record).
  using applied = framework::hyper_applied_batch<vertex_t, weight_t>;

  /// The problem of one update of `r`.
  explicit triad_count_problem(triad_count::result& r)
      : state_(&triad_count_access::state(r)), target_(&r) {}
  /// The problem of one compute() filling `st`.
  explicit triad_count_problem(triad_count_state& st) : state_(&st) {}

  // ---- lifecycle (no stage) ----

  /// The result this problem updates (nullptr for compute()).
  [[nodiscard]] const void* target() const noexcept {
    return target_;
  }
  /// The checks before anything changes: backend, placement, poisoned and stale result.
  void begin_update(framework::context& ctx, old_graph g, const requested& batch);
  /// Bind G_{t+1}: lease the workspace.
  void resume(framework::context& ctx, new_graph g, const applied& applied);
  /// Record the hypergraph state the result matches; return the workspace.
  void end_update(framework::context& ctx, new_graph g, const stats_type& stats);
  /// Mark the result unusable (a failed algorithm phase).
  void poison() noexcept {
    state_->poisoned = true;
  }
  /// The placeholder reads h2v only: the update need not keep the line graph (return true when
  /// the algorithm reads h2h; line_graph_policy::automatic then builds it once).
  [[nodiscard]] bool reads_prepared_graph() const noexcept {
    return false;
  }
  /// The budget of the algorithm phase (invariant I9, conformance check C8): nothing allocated
  /// once reserved, no host synchronization.
  [[nodiscard]] framework::budget algorithm_budget(framework::context& /*ctx*/) const noexcept {
    return framework::budget::steady_state(0);
  }

  // ---- the signed recount ----

  /// triad_count.count_minus on G_t: the placeholder counts nothing (count(+) recounts).
  void count(framework::context& ctx, old_graph g, frontier_type& f, framework::sign s,
             ownership_type rule);
  /// triad_count.count_plus on G_{t+1} (and triad_count.count in compute()): the
  /// placeholder recounts everything.
  void count(framework::context& ctx, new_graph g, frontier_type& f, framework::sign s,
             ownership_type rule);
  /// triad_count.finalize: the stats (the placeholder sets fallback_used in update()).
  void finalize(framework::context& ctx, stats_type& stats);

  // ---- compute() ----

  /// triad_count.reset: start the static solve.
  void reset(framework::context& ctx);

 private:
  /// The static solve of `h` into the state.
  void solve(framework::context& ctx, const container_type& h);

  triad_count_state* state_ = nullptr;
  const triad_count::result* target_ = nullptr;
  bool computing_ = false;
  std::optional<workspace_pool::lease<triad_count_workspace>> ws_;
  std::uint64_t before_ = 0;
};

}  // namespace dyng::detail
